<span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">    struct</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> virtq_desc </span><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">desc</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">[ Queue </span><span style="--shiki-light:#0184BC;--shiki-dark:#ABB2BF;">Size</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> ]; </span></span>
